import corpus from "@/content/articles.json";

/**
 * One of my Medium articles, as generated by scripts/build-articles.ts from
 * the Medium export. SERVER ONLY: this module imports every article body, so
 * it must never be imported from a client component. The page's article
 * count comes from content/articles-meta.json instead (see lib/content.ts).
 */
export type Article = {
  slug: string;
  title: string;
  url: string;
  publishedAt: string;
  publication?: string;
  /** Set on joint articles (published under someone else's byline): who I co-wrote it with. */
  coAuthors?: string[];
  /** One plain sentence: what it's actually about (titles are often puns). */
  summary: string;
  /** 3–6 retrieval keywords. */
  keywords: string[];
  /** Headings in order (stage-2 input). */
  outline: string[];
  /** First ~800 chars of prose (stage-2 input). */
  intro: string;
  /** Full text, Markdown. */
  body: string;
  words: number;
};

/** Imported statically so Vercel's file tracing bundles it with the function. */
export const ARTICLES = corpus as Article[];
